window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c8b178b82017485c"]={"versions": [{"id": "FIG-c8b178b82017485c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB Software-Architekturdiagramm (UML-Komponentendiagramm) auf Ebene des Virtual Functional Bus (VFB) gemäß AUTOSAR Classic Platform.\n</li><li><strong>Technischer Zweck:</strong> Strukturelle Dekomposition der <code>CrsCtrlAndAcc SW-Composition</code> (Tempomat- und Abstandsregelsystem / Cruise Control &amp; Adaptive Cruise Control) in modulare Softwarekomponenten (<code>SwComponentType</code>), inklusive Anbindung an Peripherie (Sensoren über CDD), Bedienerschnittstellen (HMI), Bordnetz/Body-Funktionen und nachgelagerte Längsdynamik-Aktuatoren (<code>Vlc</code>, <code>Esc</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Dient im Subsystem <em>Chassis / Driver Assistance</em> als Referenzarchitektur zur Definition standardisierter Funktionsgrenzen und Schnittstellenverträge zwischen OEM und Zulieferern (Modularität bei geteilter Entwicklungshoheit).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Enthaltene Komponenten (<code>CrsCtrlAndAcc SW-Composition</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>CrsCtrlAndAccStCtrl</code> (<code>AtomicSwComponentType</code>):</strong> Zentraler Zustandsmanager für CC/ACC. Verwaltet Betriebsmodi (Off, Standby, Active, Override, Error).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt Bediensignale von <code>WPII-10.5 (HMI)</code>; sendet Systemzustände/Rückmeldungen an <code>WPII-10.1 (Body)</code>; steuert Modusvorgaben an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>Acc Snsr Data Fusion</code> (<code>AtomicSwComponentType</code>):</strong> Sensordatenfusion. Führt mehrkanalige Objektdaten unterschiedlicher Erfassungstechnologien zusammen.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt vorverarbeitete Rohdaten/Objekte von <code>SurrndgsSnsr</code>; empfängt Ego-Fahrzeugdaten von <code>CrsCtrlAndAccObsvrForVehSt</code>; liefert fusionierte Spuren/Objektlisten an <code>AccObj TarSeln</code>.\n</li></ul>\n</li><li><strong><code>AccObj TarSeln</code> (<code>AtomicSwComponentType</code>):</strong> Zielobjektauswahl. Bestimmt das abstandsrelevante Führungsfahrzeug (<em>In-Lane Target</em>) anhand von Prädiktion und Trajektorienabgleich.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Input von <code>Acc Snsr Data Fusion</code> (Objekttracks) und <code>CrsCtrlAndAccObsvrForVehSt</code> (Kurvenkrümmung, Gierrate); Output (Relativabstand, Relativgeschwindigkeit) an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>CrsCtrlFree</code> (<code>AtomicSwComponentType</code>):</strong> Konventioneller Tempomat-Regler (Freifahrt). Berechnet Sollbeschleunigung zur Erreichung der gesetzten Wunschgeschwindigkeit ohne Vordermann.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Input von <code>CrsCtrlAndAccObsvrForVehSt</code> (aktuelle Geschwindigkeit); Output an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>FolwCtrlAndAArbn</code> (<code>AtomicSwComponentType</code>):</strong> Folgeregler (Distanzregelung) und Beschleunigungsarbitrierung. Arbitriert zwischen Freifahrt-Sollwert (<code>CrsCtrlFree</code>) und Distanzregler-Sollwert (<code>AccObj TarSeln</code>) unter Berücksichtigung von Systemgrenzen und Status (<code>CrsCtrlAndAccStCtrl</code>).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Output (arbitrierte Sollbeschleunigung a_req) an externen Fahrzeuglängsregler <code>Vlc</code>.\n</li></ul>\n</li><li><strong><code>CrsCtrlAndAccObsvrForVehSt</code> (<code>AtomicSwComponentType</code>):</strong> Fahrzeugzustandsbeobachter. Filtert und schätzt fahrdynamische Zustandsgrößen (Ego-Längsgeschwindigkeit, Beschleunigung, Fahrbahnsteigung).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt Sensordaten von <code>WPII-10.2 (Powertrain, Esc, Epb)</code>; versorgt intern <code>Acc Snsr Data Fusion</code>, <code>AccObj TarSeln</code>, <code>CrsCtrlFree</code> und <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Externe Boundary-Entitäten &amp; Hardware-Anbindung</h5>\n<ul class=\"fig-list\"><li><strong><code>SurrndgsSnsr</code> (Umfeldsensorik):</strong>\n<ul class=\"fig-list\"><li>Enthält n Sensorelemente (<code>Sensor [1]</code>, <code>Sensor [2]</code>, <code>Sensor [n]</code>, z. B. Radar, Kamera, Lidar) auf Hardware-Ebene.\n</li><li>Anbindung über generische Vorverarbeitungsmodule <code>SnsrDa ProcGen[1..n]</code> innerhalb eines <strong><code>Complex Device Driver</code> (CDD)</strong> zur Umgehung von Standard-Stack-Latenzen bei breitbandigen Sensorströmen.\n</li></ul>\n</li><li><strong><code>WPII-10.5 (HMI)</code>:</strong> Mensch-Maschine-Schnittstelle (Lenkstockhebel, MFL-Tasten, Menüeinstellungen).\n</li><li><strong><code>WPII-10.1 (Body)</code>:</strong> Karosserie-/Infotainment-Domäne (<code>Esc</code>, <code>Epb</code>, Kombiinstrument/Telltales).\n</li><li><strong><code>WPII-10.2 (Powertrain, Esc, Epb)</code>:</strong> Dynamik-Quellen (Raddrehzahlen, ESP-Sensorik, Motor- und Getriebestatus).\n</li><li><strong>Aktorik-Kette (<code>Esc</code>, <code>Vlc</code>, ...):</strong> <code>Vlc</code> (Vehicle Longitudinal Control) koordiniert als Aktuatormanager die Momenten- und Bremsenanforderungen an Motor, Getriebe sowie Reibbremsen (<code>Esc</code>, <code>Epb</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Port- und Konnektor-Topologie</h5>\n<ul class=\"fig-list\"><li><strong>VFB Assembly Connectors:</strong> Komponenteninterne Peer-to-Peer-Verbindungen (<code>SenderReceiverInterface</code> für dynamische Mess- und Regelwerte).\n</li><li><strong>VFB Delegation Connectors:</strong> Durchschleifung der Ports an die Begrenzung der <code>CrsCtrlAndAcc SW-Composition</code> (z. B. HMI-In, Vlc-Out, VehicleState-In).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandserfassung &amp; Schätzung (Zyklusstart):</strong>\n<ul class=\"fig-list\"><li><code>WPII-10.2</code> liefert Raddrehzahlen und Beschleunigungen; <code>CrsCtrlAndAccObsvrForVehSt</code> berechnet deterministisch gefilterte Ego-Größen.\n</li></ul>\n</li><li><strong>Sensor-Erfassung &amp; Fusion (Asynchron/Hardware-getriggert bis zyklisch synchronisiert):</strong>\n<ul class=\"fig-list\"><li><code>Sensor [1..n]</code> erfassen Umfelddaten → Vorverarbeitung in <code>SnsrDa ProcGen[1..n]</code> (CDD) → Bereitstellung an <code>Acc Snsr Data Fusion</code>.\n</li><li><code>Acc Snsr Data Fusion</code> fusioniert die Daten mit aktuellen Ego-Bewegungsvektoren.\n</li></ul>\n</li><li><strong>Trajektorienabgleich &amp; Zielauswahl:</strong>\n<ul class=\"fig-list\"><li><code>AccObj TarSeln</code> projiziert Fusionsdaten auf den prädizierten Fahrkorridor (Gierrate/Kurvenkrümmung) und identifiziert das Zielobjekt.\n</li></ul>\n</li><li><strong>Fahrerbefehl &amp; Modus-Evaluation:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlAndAccStCtrl</code> verarbeitet Tastenbetätigungen von <code>WPII-10.5 (HMI)</code> und Fahrzeug-Interlocks (<code>Esc</code>, <code>Epb</code>).\n</li></ul>\n</li><li><strong>Regelung &amp; Arbitrierung:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlFree</code> berechnet Tempomat-Sollbeschleunigung a_CC.\n</li><li><code>FolwCtrlAndAArbn</code> berechnet Distanz-Sollbeschleunigung a_ACC und arbitriert: $a_{\\text{req}} = \\min(a_{\\text{CC}}, a_{\\text{ACC}})$ (unter Berücksichtigung von Komfort- und Sicherheitsgradienten).\n</li></ul>\n</li><li><strong>Aktuierungsübergabe (Zyklusende):</strong>\n<ul class=\"fig-list\"><li>Ausgabe von a_req an <code>Vlc</code> zur Umsetzung auf Motor- und Bremsmomente.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Entkopplung OEM vs. Tier-1 (Business-Case-Schnittstellen):</strong> Die Modularisierung entkoppelt Längsregelung (<code>CrsCtrlAndAcc</code>) strikt von der Aktorik (<code>Vlc</code>). Die Beschleunigungsschnittstelle (a_req) abstrahiert die Antriebsstrangtopologie (Verbrenner, BEV, Hybrid) vollständig von der Fahrerassistenzlogik.\n</li><li><strong>CDD-Einsatz für Umfeldsensorik:</strong> Die Kapselung von <code>SnsrDa ProcGen[1..n]</code> in einem <code>Complex Device Driver</code> (CDD) ist zwingend, wenn Busprotokolle (z. B. Rohdaten via Ethernet/LVDS oder proprietäre SPI-Frames) nicht über standardisierte AUTOSAR-COM-Stacks laufen können.\n</li><li><strong>RTE-Task-Konfiguration &amp; Latenzmanagement:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlAndAccStCtrl</code>, <code>CrsCtrlFree</code> und <code>FolwCtrlAndAArbn</code> laufen typischerweise in harten Echtzeittasks (10 ms bis 20 ms Periodizität).\n</li><li><code>Acc Snsr Data Fusion</code> und <code>AccObj TarSeln</code> werden häufig mit 40 ms bis 100 ms betrieben; implizite RTE-Pufferung (<code>Rte_IRead</code>/<code>Rte_IWrite</code>) ist nötig, um Dateninkonsistenzen (Jitter, In-Task-Data-Drift) über die Fusionspipeline zu unterbinden.\n</li></ul>\n</li><li><strong>Funktionale Sicherheit (ISO 26262):</strong> Die Schnittstelle zu <code>Vlc</code> erfordert ASIL-gerechte End-to-End-Absicherung (AUTOSAR E2E Profile), Plausibilisierung der Fahrerübersteuerung (Bremspedalschalter / Override via HMI) und Plausibilisierung gegen den Ego-Zustandsbeobachter (<code>CrsCtrlAndAccObsvrForVehSt</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8175b07a4be70733", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB Software-Architekturdiagramm (UML-Komponentendiagramm) auf Ebene des Virtual Functional Bus (VFB) gemäß AUTOSAR Classic Platform.\n</li><li><strong>Technischer Zweck:</strong> Strukturelle Dekomposition der <code>CrsCtrlAndAcc SW-Composition</code> (Tempomat- und Abstandsregelsystem / Cruise Control &amp; Adaptive Cruise Control) in modulare Softwarekomponenten (<code>SwComponentType</code>), inklusive Anbindung an Peripherie (Sensoren über CDD), Bedienerschnittstellen (HMI), Bordnetz/Body-Funktionen und nachgelagerte Längsdynamik-Aktuatoren (<code>Vlc</code>, <code>Esc</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Dient im Subsystem <em>Chassis / Driver Assistance</em> als Referenzarchitektur zur Definition standardisierter Funktionsgrenzen und Schnittstellenverträge zwischen OEM und Zulieferern (Modularität bei geteilter Entwicklungshoheit).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Enthaltene Komponenten (<code>CrsCtrlAndAcc SW-Composition</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>CrsCtrlAndAccStCtrl</code> (<code>AtomicSwComponentType</code>):</strong> Zentraler Zustandsmanager für CC/ACC. Verwaltet Betriebsmodi (Off, Standby, Active, Override, Error).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt Bediensignale von <code>Multimedia Telematics HMI Domain</code>; sendet Systemzustände/Rückmeldungen an <code>Body Electronics Domain</code>; steuert Modusvorgaben an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>Acc Snsr Data Fusion</code> (<code>AtomicSwComponentType</code>):</strong> Sensordatenfusion. Führt mehrkanalige Objektdaten unterschiedlicher Erfassungstechnologien zusammen.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt vorverarbeitete Rohdaten/Objekte von <code>SurrndgsSnsr</code>; empfängt Ego-Fahrzeugdaten von <code>CrsCtrlAndAccObsvrForVehSt</code>; liefert fusionierte Spuren/Objektlisten an <code>AccObj TarSeln</code>.\n</li></ul>\n</li><li><strong><code>AccObj TarSeln</code> (<code>AtomicSwComponentType</code>):</strong> Zielobjektauswahl. Bestimmt das abstandsrelevante Führungsfahrzeug (<em>In-Lane Target</em>) anhand von Prädiktion und Trajektorienabgleich.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Input von <code>Acc Snsr Data Fusion</code> (Objekttracks) und <code>CrsCtrlAndAccObsvrForVehSt</code> (Kurvenkrümmung, Gierrate); Output (Relativabstand, Relativgeschwindigkeit) an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>CrsCtrlFree</code> (<code>AtomicSwComponentType</code>):</strong> Konventioneller Tempomat-Regler (Freifahrt). Berechnet Sollbeschleunigung zur Erreichung der gesetzten Wunschgeschwindigkeit ohne Vordermann.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Input von <code>CrsCtrlAndAccObsvrForVehSt</code> (aktuelle Geschwindigkeit); Output an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>FolwCtrlAndAArbn</code> (<code>AtomicSwComponentType</code>):</strong> Folgeregler (Distanzregelung) und Beschleunigungsarbitrierung. Arbitriert zwischen Freifahrt-Sollwert (<code>CrsCtrlFree</code>) und Distanzregler-Sollwert (<code>AccObj TarSeln</code>) unter Berücksichtigung von Systemgrenzen und Status (<code>CrsCtrlAndAccStCtrl</code>).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Output (arbitrierte Sollbeschleunigung a_req) an externen Fahrzeuglängsregler <code>Vlc</code>.\n</li></ul>\n</li><li><strong><code>CrsCtrlAndAccObsvrForVehSt</code> (<code>AtomicSwComponentType</code>):</strong> Fahrzeugzustandsbeobachter. Filtert und schätzt fahrdynamische Zustandsgrößen (Ego-Längsgeschwindigkeit, Beschleunigung, Fahrbahnsteigung).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt Sensordaten von <code>Powertrain Domain</code> (<code>Esc</code>, <code>Epb</code>); versorgt intern <code>Acc Snsr Data Fusion</code>, <code>AccObj TarSeln</code>, <code>CrsCtrlFree</code> und <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Externe Boundary-Entitäten &amp; Hardware-Anbindung</h5>\n<ul class=\"fig-list\"><li><strong><code>SurrndgsSnsr</code> (Umfeldsensorik):</strong>\n<ul class=\"fig-list\"><li>Enthält n Sensorelemente (<code>Sensor [1]</code>, <code>Sensor [2]</code>, <code>Sensor [n]</code>, z. B. Radar, Kamera, Lidar) auf Hardware-Ebene.\n</li><li>Anbindung über generische Vorverarbeitungsmodule <code>SnsrDa ProcGen[1..n]</code> innerhalb eines <strong><code>Complex Device Driver</code> (CDD)</strong> zur Umgehung von Standard-Stack-Latenzen bei breitbandigen Sensorströmen.\n</li></ul>\n</li><li><strong><code>Multimedia Telematics HMI Domain</code>:</strong> Mensch-Maschine-Schnittstelle (Lenkstockhebel, MFL-Tasten, Menüeinstellungen).\n</li><li><strong><code>Body Electronics Domain</code>:</strong> Karosserie-/Infotainment-Domäne (<code>Esc</code>, <code>Epb</code>, Kombiinstrument/Telltales).\n</li><li><strong><code>Powertrain Domain</code>:</strong> Dynamik-Quellen (<code>Esc</code>, <code>Epb</code>, Raddrehzahlen, ESP-Sensorik, Motor- und Getriebestatus).\n</li><li><strong>Aktorik-Kette (<code>Esc</code>, <code>Vlc</code>, ...):</strong> <code>Vlc</code> (Vehicle Longitudinal Control) koordiniert als Aktuatormanager die Momenten- und Bremsenanforderungen an Motor, Getriebe sowie Reibbremsen (<code>Esc</code>, <code>Epb</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Port- und Konnektor-Topologie</h5>\n<ul class=\"fig-list\"><li><strong>VFB Assembly Connectors:</strong> Komponenteninterne Peer-to-Peer-Verbindungen (<code>SenderReceiverInterface</code> für dynamische Mess- und Regelwerte).\n</li><li><strong>VFB Delegation Connectors:</strong> Durchschleifung der Ports an die Begrenzung der <code>CrsCtrlAndAcc SW-Composition</code> (z. B. HMI-In, Vlc-Out, VehicleState-In).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandserfassung &amp; Schätzung (Zyklusstart):</strong>\n<ul class=\"fig-list\"><li><code>Powertrain Domain</code> liefert Raddrehzahlen und Beschleunigungen; <code>CrsCtrlAndAccObsvrForVehSt</code> berechnet deterministisch gefilterte Ego-Größen.\n</li></ul>\n</li><li><strong>Sensor-Erfassung &amp; Fusion (Asynchron/Hardware-getriggert bis zyklisch synchronisiert):</strong>\n<ul class=\"fig-list\"><li><code>Sensor [1..n]</code> erfassen Umfelddaten → Vorverarbeitung in <code>SnsrDa ProcGen[1..n]</code> (CDD) → Bereitstellung an <code>Acc Snsr Data Fusion</code>.\n</li><li><code>Acc Snsr Data Fusion</code> fusioniert die Daten mit aktuellen Ego-Bewegungsvektoren.\n</li></ul>\n</li><li><strong>Trajektorienabgleich &amp; Zielauswahl:</strong>\n<ul class=\"fig-list\"><li><code>AccObj TarSeln</code> projiziert Fusionsdaten auf den prädizierten Fahrkorridor (Gierrate/Kurvenkrümmung) und identifiziert das Zielobjekt.\n</li></ul>\n</li><li><strong>Fahrerbefehl &amp; Modus-Evaluation:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlAndAccStCtrl</code> verarbeitet Tastenbetätigungen von <code>Multimedia Telematics HMI Domain</code> und Fahrzeug-Interlocks (<code>Esc</code>, <code>Epb</code>).\n</li></ul>\n</li><li><strong>Regelung &amp; Arbitrierung:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlFree</code> berechnet Tempomat-Sollbeschleunigung a_CC.\n</li><li><code>FolwCtrlAndAArbn</code> berechnet Distanz-Sollbeschleunigung a_ACC und arbitriert: $a_{\\text{req}} = \\min(a_{\\text{CC}}, a_{\\text{ACC}})$ (unter Berücksichtigung von Komfort- und Sicherheitsgradienten).\n</li></ul>\n</li><li><strong>Aktuierungsübergabe (Zyklusende):</strong>\n<ul class=\"fig-list\"><li>Ausgabe von a_req an <code>Vlc</code> zur Umsetzung auf Motor- und Bremsmomente.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Entkopplung OEM vs. Tier-1 (Business-Case-Schnittstellen):</strong> Die Modularisierung entkoppelt Längsregelung (<code>CrsCtrlAndAcc</code>) strikt von der Aktorik (<code>Vlc</code>). Die Beschleunigungsschnittstelle (a_req) abstrahiert die Antriebsstrangtopologie (Verbrenner, BEV, Hybrid) vollständig von der Fahrerassistenzlogik.\n</li><li><strong>CDD-Einsatz für Umfeldsensorik:</strong> Die Kapselung von <code>SnsrDa ProcGen[1..n]</code> in einem <code>Complex Device Driver</code> (CDD) ist zwingend, wenn Busprotokolle (z. B. Rohdaten via Ethernet/LVDS oder proprietäre SPI-Frames) nicht über standardisierte AUTOSAR-COM-Stacks laufen können.\n</li><li><strong>RTE-Task-Konfiguration &amp; Latenzmanagement:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlAndAccStCtrl</code>, <code>CrsCtrlFree</code> und <code>FolwCtrlAndAArbn</code> laufen typischerweise in harten Echtzeittasks (10 ms bis 20 ms Periodizität).\n</li><li><code>Acc Snsr Data Fusion</code> und <code>AccObj TarSeln</code> werden häufig mit 40 ms bis 100 ms betrieben; implizite RTE-Pufferung (<code>Rte_IRead</code>/<code>Rte_IWrite</code>) ist nötig, um Dateninkonsistenzen (Jitter, In-Task-Data-Drift) über die Fusionspipeline zu unterbinden.\n</li></ul>\n</li><li><strong>Funktionale Sicherheit (ISO 26262):</strong> Die Schnittstelle zu <code>Vlc</code> erfordert ASIL-gerechte End-to-End-Absicherung (AUTOSAR E2E Profile), Plausibilisierung der Fahrerübersteuerung (Bremspedalschalter / Override via HMI) und Plausibilisierung gegen den Ego-Zustandsbeobachter (<code>CrsCtrlAndAccObsvrForVehSt</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9b02d6c22ef2a955", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB Software-Architekturdiagramm (UML-Komponentendiagramm) auf Ebene des Virtual Functional Bus (VFB) gemäß AUTOSAR Classic Platform.\n</li><li><strong>Technischer Zweck:</strong> Strukturelle Dekomposition der <code>CrsCtrlAndAcc SW-Composition</code> (Tempomat- und Abstandsregelsystem / Cruise Control &amp; Adaptive Cruise Control) in modulare Softwarekomponenten (<code>SwComponentType</code>), inklusive Anbindung an Peripherie (Sensoren über CDD), Bedienerschnittstellen (HMI), Bordnetz/Body-Funktionen und nachgelagerte Längsdynamik-Aktuatoren (<code>Vlc</code>, <code>Esc</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Dient im Subsystem <em>Chassis / Driver Assistance</em> als Referenzarchitektur zur Definition standardisierter Funktionsgrenzen und Schnittstellenverträge zwischen OEM und Zulieferern (Modularität bei geteilter Entwicklungshoheit).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Enthaltene Komponenten (<code>CrsCtrlAndAcc SW-Composition</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>CrsCtrlAndAccStCtrl</code> (<code>AtomicSwComponentType</code>):</strong> Zentraler Zustandsmanager für CC/ACC. Verwaltet Betriebsmodi (Off, Standby, Active, Override, Error).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt Bediensignale von <code>Multimedia Telematics HMI Domain</code>; sendet Systemzustände/Rückmeldungen an <code>Body Electronics Domain</code>; steuert Modusvorgaben an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>Acc Snsr Data Fusion</code> (<code>AtomicSwComponentType</code>):</strong> Sensordatenfusion. Führt mehrkanalige Objektdaten unterschiedlicher Erfassungstechnologien zusammen.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt vorverarbeitete Rohdaten/Objekte von <code>SurrndgsSnsr</code>; empfängt Ego-Fahrzeugdaten von <code>CrsCtrlAndAccObsvrForVehSt</code>; liefert fusionierte Spuren/Objektlisten an <code>AccObj TarSeln</code>.\n</li></ul>\n</li><li><strong><code>AccObj TarSeln</code> (<code>AtomicSwComponentType</code>):</strong> Zielobjektauswahl. Bestimmt das abstandsrelevante Führungsfahrzeug (<em>In-Lane Target</em>) anhand von Prädiktion und Trajektorienabgleich.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Input von <code>Acc Snsr Data Fusion</code> (Objekttracks) und <code>CrsCtrlAndAccObsvrForVehSt</code> (Kurvenkrümmung, Gierrate); Output (Relativabstand, Relativgeschwindigkeit) an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>CrsCtrlFree</code> (<code>AtomicSwComponentType</code>):</strong> Konventioneller Tempomat-Regler (Freifahrt). Berechnet Sollbeschleunigung zur Erreichung der gesetzten Wunschgeschwindigkeit ohne Vordermann.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Input von <code>CrsCtrlAndAccObsvrForVehSt</code> (aktuelle Geschwindigkeit); Output an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>FolwCtrlAndAArbn</code> (<code>AtomicSwComponentType</code>):</strong> Folgeregler (Distanzregelung) und Beschleunigungsarbitrierung. Arbitriert zwischen Freifahrt-Sollwert (<code>CrsCtrlFree</code>) und Distanzregler-Sollwert (<code>AccObj TarSeln</code>) unter Berücksichtigung von Systemgrenzen und Status (<code>CrsCtrlAndAccStCtrl</code>).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Output (arbitrierte Sollbeschleunigung a_req) an externen Fahrzeuglängsregler <code>Vlc</code>.\n</li></ul>\n</li><li><strong><code>CrsCtrlAndAccObsvrForVehSt</code> (<code>AtomicSwComponentType</code>):</strong> Fahrzeugzustandsbeobachter. Filtert und schätzt fahrdynamische Zustandsgrößen (Ego-Längsgeschwindigkeit, Beschleunigung, Fahrbahnsteigung).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt Sensordaten von <code>Powertrain Domain</code> (<code>Esc</code>, <code>Epb</code>); versorgt intern <code>Acc Snsr Data Fusion</code>, <code>AccObj TarSeln</code>, <code>CrsCtrlFree</code> und <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Externe Boundary-Entitäten &amp; Hardware-Anbindung</h5>\n<ul class=\"fig-list\"><li><strong><code>SurrndgsSnsr</code> (Umfeldsensorik):</strong>\n<ul class=\"fig-list\"><li>Enthält n Sensorelemente (<code>Sensor [1]</code>, <code>Sensor [2]</code>, <code>Sensor [n]</code>, z. B. Radar, Kamera, Lidar) auf Hardware-Ebene.\n</li><li>Anbindung über generische Vorverarbeitungsmodule <code>SnsrDa ProcGen[1..n]</code> innerhalb eines <strong><code>Complex Device Driver</code> (CDD)</strong> zur Umgehung von Standard-Stack-Latenzen bei breitbandigen Sensorströmen.\n</li></ul>\n</li><li><strong><code>Multimedia Telematics HMI Domain</code>:</strong> Mensch-Maschine-Schnittstelle (Lenkstockhebel, MFL-Tasten, Menüeinstellungen).\n</li><li><strong><code>Body Electronics Domain</code>:</strong> Karosserie-/Infotainment-Domäne (<code>Esc</code>, <code>Epb</code>, Kombiinstrument/Telltales).\n</li><li><strong><code>Powertrain Domain</code>:</strong> Dynamik-Quellen (<code>Esc</code>, <code>Epb</code>, Raddrehzahlen, ESP-Sensorik, Motor- und Getriebestatus).\n</li><li><strong>Aktorik-Kette (<code>Esc</code>, <code>Vlc</code>, ...):</strong> <code>Vlc</code> (Vehicle Longitudinal Control) koordiniert als Aktuatormanager die Momenten- und Bremsenanforderungen an Motor, Getriebe sowie Reibbremsen (<code>Esc</code>, <code>Epb</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Port- und Konnektor-Topologie</h5>\n<ul class=\"fig-list\"><li><strong>VFB Assembly Connectors:</strong> Komponenteninterne Peer-to-Peer-Verbindungen (<code>SenderReceiverInterface</code> für dynamische Mess- und Regelwerte).\n</li><li><strong>VFB Delegation Connectors:</strong> Durchschleifung der Ports an die Begrenzung der <code>CrsCtrlAndAcc SW-Composition</code> (z. B. HMI-In, Vlc-Out, VehicleState-In).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandserfassung &amp; Schätzung (Zyklusstart):</strong>\n<ul class=\"fig-list\"><li><code>Powertrain Domain</code> liefert Raddrehzahlen und Beschleunigungen; <code>CrsCtrlAndAccObsvrForVehSt</code> berechnet deterministisch gefilterte Ego-Größen.\n</li></ul>\n</li><li><strong>Sensor-Erfassung &amp; Fusion (Asynchron/Hardware-getriggert bis zyklisch synchronisiert):</strong>\n<ul class=\"fig-list\"><li><code>Sensor [1..n]</code> erfassen Umfelddaten → Vorverarbeitung in <code>SnsrDa ProcGen[1..n]</code> (CDD) → Bereitstellung an <code>Acc Snsr Data Fusion</code>.\n</li><li><code>Acc Snsr Data Fusion</code> fusioniert die Daten mit aktuellen Ego-Bewegungsvektoren.\n</li></ul>\n</li><li><strong>Trajektorienabgleich &amp; Zielauswahl:</strong>\n<ul class=\"fig-list\"><li><code>AccObj TarSeln</code> projiziert Fusionsdaten auf den prädizierten Fahrkorridor (Gierrate/Kurvenkrümmung) und identifiziert das Zielobjekt.\n</li></ul>\n</li><li><strong>Fahrerbefehl &amp; Modus-Evaluation:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlAndAccStCtrl</code> verarbeitet Tastenbetätigungen von <code>Multimedia Telematics HMI Domain</code> und Fahrzeug-Interlocks (<code>Esc</code>, <code>Epb</code>).\n</li></ul>\n</li><li><strong>Regelung &amp; Arbitrierung:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlFree</code> berechnet Tempomat-Sollbeschleunigung a_CC.\n</li><li><code>FolwCtrlAndAArbn</code> berechnet Distanz-Sollbeschleunigung a_ACC und arbitriert: $a_{\\text{req}} = \\min(a_{\\text{CC}}, a_{\\text{ACC}})$ (unter Berücksichtigung von Komfort- und Sicherheitsgradienten).\n</li></ul>\n</li><li><strong>Aktuierungsübergabe (Zyklusende):</strong>\n<ul class=\"fig-list\"><li>Ausgabe von a_req an <code>Vlc</code> zur Umsetzung auf Motor- und Bremsmomente.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Entkopplung OEM vs. Tier-1 (Business-Case-Schnittstellen):</strong> Die Modularisierung entkoppelt Längsregelung (<code>CrsCtrlAndAcc</code>) strikt von der Aktorik (<code>Vlc</code>). Die Beschleunigungsschnittstelle (a_req) abstrahiert die Antriebsstrangtopologie (Verbrenner, BEV, Hybrid) vollständig von der Fahrerassistenzlogik.\n</li><li><strong>CDD-Einsatz für Umfeldsensorik:</strong> Die Kapselung von <code>SnsrDa ProcGen[1..n]</code> in einem <code>Complex Device Driver</code> (CDD) ist zwingend, wenn Busprotokolle (z. B. Rohdaten via Ethernet/LVDS oder proprietäre SPI-Frames) nicht über standardisierte AUTOSAR-COM-Stacks laufen können.\n</li><li><strong>RTE-Task-Konfiguration &amp; Latenzmanagement:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlAndAccStCtrl</code>, <code>CrsCtrlFree</code> und <code>FolwCtrlAndAArbn</code> laufen typischerweise in harten Echtzeittasks (10 ms bis 20 ms Periodizität).\n</li><li><code>Acc Snsr Data Fusion</code> und <code>AccObj TarSeln</code> werden häufig mit 40 ms bis 100 ms betrieben; implizite RTE-Pufferung (<code>Rte_IRead</code>/<code>Rte_IWrite</code>) ist nötig, um Dateninkonsistenzen (Jitter, In-Task-Data-Drift) über die Fusionspipeline zu unterbinden.\n</li></ul>\n</li><li><strong>Funktionale Sicherheit (ISO 26262):</strong> Die Schnittstelle zu <code>Vlc</code> erfordert ASIL-gerechte End-to-End-Absicherung (AUTOSAR E2E Profile), Plausibilisierung der Fahrerübersteuerung (Bremspedalschalter / Override via HMI) und Plausibilisierung gegen den Ego-Zustandsbeobachter (<code>CrsCtrlAndAccObsvrForVehSt</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e4ecb82bb35a7e3e", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB Software-Architekturdiagramm (UML-Komponentendiagramm) auf Ebene des Virtual Functional Bus (VFB) gemäß AUTOSAR Classic Platform.\n</li><li><strong>Technischer Zweck:</strong> Strukturelle Dekomposition der <code>CrsCtrlAndAcc SW-Composition</code> (Tempomat- und Abstandsregelsystem / Cruise Control &amp; Adaptive Cruise Control) in modulare Softwarekomponenten (<code>SwComponentType</code>), inklusive Anbindung an Peripherie (Sensoren über CDD), Bedienerschnittstellen (HMI), Bordnetz/Body-Funktionen und nachgelagerte Längsdynamik-Aktuatoren (<code>Vlc</code>, <code>Esc</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Dient im Subsystem <em>Chassis / Driver Assistance</em> als Referenzarchitektur zur Definition standardisierter Funktionsgrenzen und Schnittstellenverträge zwischen OEM und Zulieferern (Modularität bei geteilter Entwicklungshoheit).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Enthaltene Komponenten (<code>CrsCtrlAndAcc SW-Composition</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>CrsCtrlAndAccStCtrl</code> (<code>AtomicSwComponentType</code>):</strong> Zentraler Zustandsmanager für CC/ACC. Verwaltet Betriebsmodi (Off, Standby, Active, Override, Error).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt Bediensignale von <code>Multimedia Telematics HMI Domain</code>; sendet Systemzustände/Rückmeldungen an <code>Body Electronics Domain</code>; steuert Modusvorgaben an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>Acc Snsr Data Fusion</code> (<code>AtomicSwComponentType</code>):</strong> Sensordatenfusion. Führt mehrkanalige Objektdaten unterschiedlicher Erfassungstechnologien zusammen.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt vorverarbeitete Rohdaten/Objekte von <code>SurrndgsSnsr</code>; empfängt Ego-Fahrzeugdaten von <code>CrsCtrlAndAccObsvrForVehSt</code>; liefert fusionierte Spuren/Objektlisten an <code>AccObj TarSeln</code>.\n</li></ul>\n</li><li><strong><code>AccObj TarSeln</code> (<code>AtomicSwComponentType</code>):</strong> Zielobjektauswahl. Bestimmt das abstandsrelevante Führungsfahrzeug (<em>In-Lane Target</em>) anhand von Prädiktion und Trajektorienabgleich.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Input von <code>Acc Snsr Data Fusion</code> (Objekttracks) und <code>CrsCtrlAndAccObsvrForVehSt</code> (Kurvenkrümmung, Gierrate); Output (Relativabstand, Relativgeschwindigkeit) an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>CrsCtrlFree</code> (<code>AtomicSwComponentType</code>):</strong> Konventioneller Tempomat-Regler (Freifahrt). Berechnet Sollbeschleunigung zur Erreichung der gesetzten Wunschgeschwindigkeit ohne Vordermann.\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Input von <code>CrsCtrlAndAccObsvrForVehSt</code> (aktuelle Geschwindigkeit); Output an <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li><li><strong><code>FolwCtrlAndAArbn</code> (<code>AtomicSwComponentType</code>):</strong> Folgeregler (Distanzregelung) und Beschleunigungsarbitrierung. Arbitriert zwischen Freifahrt-Sollwert (<code>CrsCtrlFree</code>) und Distanzregler-Sollwert (<code>AccObj TarSeln</code>) unter Berücksichtigung von Systemgrenzen und Status (<code>CrsCtrlAndAccStCtrl</code>).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Output (arbitrierte Sollbeschleunigung a_req) an externen Fahrzeuglängsregler <code>Vlc</code>.\n</li></ul>\n</li><li><strong><code>CrsCtrlAndAccObsvrForVehSt</code> (<code>AtomicSwComponentType</code>):</strong> Fahrzeugzustandsbeobachter. Filtert und schätzt fahrdynamische Zustandsgrößen (Ego-Längsgeschwindigkeit, Beschleunigung, Fahrbahnsteigung).\n<ul class=\"fig-list\"><li><em>Schnittstellen:</em> Empfängt Sensordaten von <code>Powertrain Domain</code> (<code>Esc</code>, <code>Epb</code>); versorgt intern <code>Acc Snsr Data Fusion</code>, <code>AccObj TarSeln</code>, <code>CrsCtrlFree</code> und <code>FolwCtrlAndAArbn</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Externe Boundary-Entitäten &amp; Hardware-Anbindung</h5>\n<ul class=\"fig-list\"><li><strong><code>SurrndgsSnsr</code> (Umfeldsensorik):</strong>\n<ul class=\"fig-list\"><li>Enthält n Sensorelemente (<code>Sensor [1]</code>, <code>Sensor [2]</code>, <code>Sensor [n]</code>, z. B. Radar, Kamera, Lidar) auf Hardware-Ebene.\n</li><li>Anbindung über generische Vorverarbeitungsmodule <code>SnsrDa ProcGen[1..n]</code> innerhalb eines <strong><code>Complex Device Driver</code> (CDD)</strong> zur Umgehung von Standard-Stack-Latenzen bei breitbandigen Sensorströmen.\n</li></ul>\n</li><li><strong><code>Multimedia Telematics HMI Domain</code>:</strong> Mensch-Maschine-Schnittstelle (Lenkstockhebel, MFL-Tasten, Menüeinstellungen).\n</li><li><strong><code>Body Electronics Domain</code>:</strong> Karosserie-/Infotainment-Domäne (<code>Esc</code>, <code>Epb</code>, Kombiinstrument/Telltales).\n</li><li><strong><code>Powertrain Domain</code>:</strong> Dynamik-Quellen (<code>Esc</code>, <code>Epb</code>, Raddrehzahlen, ESP-Sensorik, Motor- und Getriebestatus).\n</li><li><strong>Aktorik-Kette (<code>Esc</code>, <code>Vlc</code>, ...):</strong> <code>Vlc</code> (Vehicle Longitudinal Control) koordiniert als Aktuatormanager die Momenten- und Bremsenanforderungen an Motor, Getriebe sowie Reibbremsen (<code>Esc</code>, <code>Epb</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Port- und Konnektor-Topologie</h5>\n<ul class=\"fig-list\"><li><strong>VFB Assembly Connectors:</strong> Komponenteninterne Peer-to-Peer-Verbindungen (<code>SenderReceiverInterface</code> für dynamische Mess- und Regelwerte).\n</li><li><strong>VFB Delegation Connectors:</strong> Durchschleifung der Ports an die Begrenzung der <code>CrsCtrlAndAcc SW-Composition</code> (z. B. HMI-In, Vlc-Out, VehicleState-In).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandserfassung &amp; Schätzung (Zyklusstart):</strong>\n<ul class=\"fig-list\"><li><code>Powertrain Domain</code> liefert Raddrehzahlen und Beschleunigungen; <code>CrsCtrlAndAccObsvrForVehSt</code> berechnet deterministisch gefilterte Ego-Größen.\n</li></ul>\n</li><li><strong>Sensor-Erfassung &amp; Fusion (Asynchron/Hardware-getriggert bis zyklisch synchronisiert):</strong>\n<ul class=\"fig-list\"><li><code>Sensor [1..n]</code> erfassen Umfelddaten → Vorverarbeitung in <code>SnsrDa ProcGen[1..n]</code> (CDD) → Bereitstellung an <code>Acc Snsr Data Fusion</code>.\n</li><li><code>Acc Snsr Data Fusion</code> fusioniert die Daten mit aktuellen Ego-Bewegungsvektoren.\n</li></ul>\n</li><li><strong>Trajektorienabgleich &amp; Zielauswahl:</strong>\n<ul class=\"fig-list\"><li><code>AccObj TarSeln</code> projiziert Fusionsdaten auf den prädizierten Fahrkorridor (Gierrate/Kurvenkrümmung) und identifiziert das Zielobjekt.\n</li></ul>\n</li><li><strong>Fahrerbefehl &amp; Modus-Evaluation:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlAndAccStCtrl</code> verarbeitet Tastenbetätigungen von <code>Multimedia Telematics HMI Domain</code> und Fahrzeug-Interlocks (<code>Esc</code>, <code>Epb</code>).\n</li></ul>\n</li><li><strong>Regelung &amp; Arbitrierung:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlFree</code> berechnet Tempomat-Sollbeschleunigung a_CC.\n</li><li><code>FolwCtrlAndAArbn</code> berechnet Distanz-Sollbeschleunigung a_ACC und arbitriert: $a_{\\text{req}} = \\min(a_{\\text{CC}}, a_{\\text{ACC}})$ (unter Berücksichtigung von Komfort- und Sicherheitsgradienten).\n</li></ul>\n</li><li><strong>Aktuierungsübergabe (Zyklusende):</strong>\n<ul class=\"fig-list\"><li>Ausgabe von a_req an <code>Vlc</code> zur Umsetzung auf Motor- und Bremsmomente.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Entkopplung OEM vs. Tier-1 (Business-Case-Schnittstellen):</strong> Die Modularisierung entkoppelt Längsregelung (<code>CrsCtrlAndAcc</code>) strikt von der Aktorik (<code>Vlc</code>). Die Beschleunigungsschnittstelle (a_req) abstrahiert die Antriebsstrangtopologie (Verbrenner, BEV, Hybrid) vollständig von der Fahrerassistenzlogik.\n</li><li><strong>CDD-Einsatz für Umfeldsensorik:</strong> Die Kapselung von <code>SnsrDa ProcGen[1..n]</code> in einem <code>Complex Device Driver</code> (CDD) ist zwingend, wenn Busprotokolle (z. B. Rohdaten via Ethernet/LVDS oder proprietäre SPI-Frames) nicht über standardisierte AUTOSAR-COM-Stacks laufen können.\n</li><li><strong>RTE-Task-Konfiguration &amp; Latenzmanagement:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlAndAccStCtrl</code>, <code>CrsCtrlFree</code> und <code>FolwCtrlAndAArbn</code> laufen typischerweise in harten Echtzeittasks (10 ms bis 20 ms Periodizität).\n</li><li><code>Acc Snsr Data Fusion</code> und <code>AccObj TarSeln</code> werden häufig mit 40 ms bis 100 ms betrieben; implizite RTE-Pufferung (<code>Rte_IRead</code>/<code>Rte_IWrite</code>) ist nötig, um Dateninkonsistenzen (Jitter, In-Task-Data-Drift) über die Fusionspipeline zu unterbinden.\n</li></ul>\n</li><li><strong>Funktionale Sicherheit (ISO 26262):</strong> Die Schnittstelle zu <code>Vlc</code> erfordert ASIL-gerechte End-to-End-Absicherung (AUTOSAR E2E Profile), Plausibilisierung der Fahrerübersteuerung (Bremspedalschalter / Override via HMI) und Plausibilisierung gegen den Ego-Zustandsbeobachter (<code>CrsCtrlAndAccObsvrForVehSt</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c8b178b82017485c", "to": "FIG-8175b07a4be70733", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>Multimedia Telematics HMI Domain</code>: Umbenennung des externen Schnittstellenblocks von <code>WPII-10.5 (HMI)</code>.\n</li><li><code>Body Electronics Domain</code>: Umbenennung des externen Schnittstellenblocks von <code>WPII-10.1 (Body)</code>.\n</li><li><code>Powertrain Domain</code>: Umbenennung des externen Schnittstellenblocks von <code>WPII-10.2 (Powertrain)</code>.\n</li><li>Layout: Erweiterung des unteren Bildausschnitts, wodurch die Beschriftung des Powertrain-Blocks samt Fortsetzungspunkten (<code>....</code>) vollständig dargestellt wird.\n</li></ul>"}, {"from": "FIG-8175b07a4be70733", "to": "FIG-9b02d6c22ef2a955", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9b02d6c22ef2a955", "to": "FIG-e4ecb82bb35a7e3e", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
